WITH target_routes AS ( /* Optimization 1: Moving massive IN clause to a CTE to prevent internal engine errors */ SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (122, 123), (123, 122), (123, 141), (124, 122), (122, 124), (124, 134), (122, 71756), (757, 733), (71756, 122), (130, 624), (74820, 74694), (624, 130), (74694, 74820), (130, 309), (122, 216), (124, 123), (134, 122), (130, 575), (124, 462), (123, 124), (462, 124), (122, 71929), (130, 641), (575, 130), (141, 126), (130, 1476), (233, 123), (74661, 122), (641, 130), (248, 134), (126, 141), (122, 995), (130, 361), (995, 122), (71425, 122), (309, 462), (361, 130), (1476, 130), (65976, 130), (122, 95218), (551, 473), (130, 95083), (130, 311), (141, 71929), (624, 124), (313, 551), (95218, 122), (1514, 733), (74701, 79589), (71929, 141), (1290, 733), (123, 504), (122, 78796), (470, 1169), (123, 506), (1382, 130), (733, 1290), (71756, 123), (1437, 733), (624, 361), (70015, 777), (130, 1384), (74701, 93059), (313, 94152), (733, 1437), (361, 624), (70024, 83760), (1384, 130), (122, 923), (130, 65907), (309, 575), (93947, 70014), (575, 309), (1443, 807), (807, 1290), (624, 444), (130, 65859), (833, 777), (646, 130), (1429, 1290), (130, 622), (70015, 833), (122, 65930), (1429, 777), (629, 130), (1290, 1429), (141, 124), (622, 130), (70015, 1290), (777, 1429) ) AS t(s, d) ), offer_tuple AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.rb_user_id, s.src_id, s.dest_id FROM "user_interaction"."search_route_details" s -- LEFT JOIN bharat_sds sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id -- JOIN valid v ON s.mri_session_id = v.valid_session WHERE s.__time >= TIMESTAMP '2026-01-06 18:30:00' AND s.__time < TIMESTAMP '2026-01-27 18:30:00' -- AND (s.src_id, s.dest_id) IN ((69283, 65782)) -- AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND s.os = 'Android' AND s.country = 'IND' ), -- Deduped Funnel Steps (1 row per session + route_id) srp_deduped AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', DATE_ADD('minute', 330, "__time")) AS DATE) AS doi, -- CAST(DATE_TRUNC('hour', DATE_ADD('minute', 330, "__time")) AS TIMESTAMP) AS day_hour, s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, -- rm.region, -- CASE WHEN s.route_id IN (SELECT DISTINCT route_id FROM offer_tuple) THEN 'Offer Tuple' ELSE 'non-Offer Tuple' END AS tuple_type, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 THEN '1. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 1 THEN '2. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 2 THEN '3. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) > 2 THEN '4. DBD 2+' ELSE '5. Others' END AS search_day, CASE -- WHEN (s.src_id, s.dest_id) IN ((69283, 65782)) THEN 'Test Route' -- WHEN (s.src_id, s.dest_id) IN (SELECT DISTINCT src_id, dest_id FROM bharat_sds) THEN 'bharat_sds' WHEN (s.src_id, s.dest_id) IN (SELECT DISTINCT src_id, dest_id FROM offer_tuple) THEN 'bharat_sds dynamic' ELSE 'Other SDs' END AS route_type FROM "user_interaction"."search_route_details" s INNER JOIN target_routes t ON s.src_id = t.src_id AND s.dest_id = t.dest_id WHERE s.__time >= TIMESTAMP '2026-01-06 18:30:00' AND s.__time < TIMESTAMP '2026-01-27 18:30:00' -- AND (s.src_id, s.dest_id) IN ((69283, 65782)) -- AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'Android' AND s.country = 'IND' AND s.status = 200 -- AND -- LIMIT 100 -- GROUP BY 1,2,3,4,5,6,7,8,9 ) SELECT -- DISTINCT srp.doi, -- srp.day_hour, srp.search_day, -- 'Any DBD' search_day, -- srp.region, UPPER(srp.user_type) as user_type, -- srp.route_type, 'Target Routes' AS route_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT v.mri_session_id) AS dbs_viewed_sessions FROM srp_deduped srp LEFT JOIN offer_tuple v ON v.mri_session_id = srp.mri_session_id AND v.src_id = srp.src_id AND v.dest_id = srp.dest_id GROUP BY 1,2,3,4,5 ORDER BY 1, 2, 4, 3 DESC
